#[path="../src/semantic.rs"] mod semantic;
use semantic::SemanticService;use std::{time::{Duration,Instant},thread};
#[test]fn revision_available_only_when_current(){let p=std::env::temp_dir().join(format!("atlas-sem-rev-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();let s=SemanticService::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();assert_eq!(s.revision(&p),None);s.enqueue(&p,None).unwrap();assert_eq!(s.revision(&p),None);let end=Instant::now()+Duration::from_secs(60);while Instant::now()<end && !s.status(&p)["available"].as_bool().unwrap(){thread::sleep(Duration::from_millis(30));}let old=s.revision(&p).expect("ready revision");s.enqueue(&p,Some("x")).unwrap();assert_eq!(s.revision(&p),None);let end=Instant::now()+Duration::from_secs(60);while Instant::now()<end && !s.status(&p)["available"].as_bool().unwrap(){thread::sleep(Duration::from_millis(30));}assert!(s.revision(&p).unwrap()>old);s.close(&p).unwrap();assert_eq!(s.revision(&p),None);std::fs::remove_dir_all(p).unwrap();}
